              Global Settings
            </SidebarMenuButton>
          </SidebarMenuItem>
          <SidebarMenuItem>
            <SidebarMenuButton
              icon={isDark ? SunIcon : MoonIcon}
              onClick={() => setTheme(isDark ? "light" : "dark")}
