                         ) : (
                           <PlayIcon />
                         )}
                       </SidebarMenuAction>
                     </Tooltip>
                     <Tooltip content="Rename" side="top">
                       <SidebarMenuAction
                         aria-label="Rename"
                         onClick={() => setRenameOpen(true)}
                       >
                         <PencilIcon />
                       </SidebarMenuAction>
                     </Tooltip>
                     <DropdownMenu>
                       <DropdownTrigger
                         render={
                           <SidebarMenuAction aria-label="More options">
                             <MoreVerticalIcon />
                           </SidebarMenuAction>
                         }
                       />
                       {/* 240px — the header/footer trigger width */}
                       <DropdownContent
                         className="min-w-0 w-[240px]"
                         align="start"
                         sideOffset={4}
                       >
                         <MenuItem
                           index={0}
                           icon={PlayIcon}
                           label="Run"
                           onSelect={() => {}}
                         />
                         <MenuItem
                           index={1}
                           icon={PencilIcon}
                           label="Rename"
                           onSelect={() => setRenameOpen(true)}
                         />
                         <MenuItem
                           index={2}
                           icon={LinkIcon}
                           label="Share"
                           onSelect={() =>
                             setWorkflowDialogOpen([true, "share"])
                           }
                         />
 
                         <DropdownSeparator />
                         {/* a confirmation dialog to delete this thread permanently, includign cascade everything from database */}
                         <MenuItem
                           index={4}
                           icon={DeleteIcon}
                           label="Delete"
                           onSelect={() =>
                             setWorkflowDeleteOpen([workflowDeleteOpen[0], true])
                           }
                         />
                       </DropdownContent>
                     </DropdownMenu>
                   </SidebarMenuActions>
                 </SidebarMenuItem>
               ))}
             </SidebarMenu>
           </SidebarGroup>
         ))}
       </SidebarContent>
       <SidebarFooter>
         {callouts.length > 0 && (
           <Card
             size="compact"
             dismissible
             onDismiss={() => dismiss(1)}
             label="Aurora 2 is here — longer context, faster agents"
             className={`rounded-xl overflow-hidden min-h-0 transition-[background-color,box-shadow] duration-80 ${surfaceClasses(level, 2)} ${surfaceHoverClasses(level + 1, 3)} shadow-(--shadow-2-inset) hover:shadow-(--shadow-3-inset)`}
           >
             {/* swap for your artwork */}
