               className="aspect-[2/1] max-h-28"
             />
             <CardHeader className="gap-0 pt-3">
               <CardTitle className="truncate">Aurora 2 is here</CardTitle>
               <CardDescription className="truncate">
                 Longer context, faster agents
               </CardDescription>
             </CardHeader>
           </Card>
         )}
         {/* vertical: actions stack above the user row */}
         <SidebarMenu>
           <SidebarMenuItem>
             <SidebarMenuButton
               icon={FooterSettingsIcon}
               onClick={() => setSettingsOpen(true)}
             >
               Global Settings
             </SidebarMenuButton>
           </SidebarMenuItem>
           <SidebarMenuItem>
             <SidebarMenuButton
               icon={isDark ? SunIcon : MoonIcon}
               onClick={() => setTheme(isDark ? "light" : "dark")}
             >
               Toggle Theme
             </SidebarMenuButton>
           </SidebarMenuItem>
         </SidebarMenu>
         <SidebarUserFooter
           name="Jane Doe"
           avatar={
             <span className="flex size-5 items-center justify-center rounded-full bg-muted-foreground text-[10px] text-background">
               J
             </span>
           }
           menu={
             <>
               <MenuItem
                 index={0}
                 icon={UserIcon}
                 label="Profile"
                 onSelect={() => {}}
               />
             
               <MenuItem
                 index={2}
                 icon={ArrowLeftIcon}
                 label="Log out"
                 onSelect={() => {}}
               />
             </>
           }
         />
       </SidebarFooter>
     </Sidebar>
   );
 }

